<?php declare(strict_types=1); $base=config('app.base_path'); $esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<div class="page-header"><div><h1>Restaurant Coupons</h1><p>Create promotional codes that can be tested through the customer-order flow.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= $base ?>/restaurant/coupons/create">Create Coupon</a></div></div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Restaurant</th><th>Discount</th><th>Minimum</th><th>Validity</th><th>Usage</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($coupons as $c): ?><tr><td><strong><?= $esc($c['code']) ?></strong><br><small><?= $esc($c['name']) ?></small></td><td><?= $esc($c['restaurant_name']) ?></td><td><?= $c['discount_type']==='PERCENT'?number_format((float)$c['discount_value'],2).' %':'₹'.number_format((float)$c['discount_value'],2) ?><?php if($c['maximum_discount']!==null): ?><br><small>Max ₹<?= number_format((float)$c['maximum_discount'],2) ?></small><?php endif; ?></td><td>₹<?= number_format((float)$c['minimum_order_amount'],2) ?></td><td><?= $esc($c['starts_at']??'Any') ?> → <?= $esc($c['ends_at']??'Any') ?></td><td><?= (int)$c['used_count'] ?><?= $c['usage_limit']!==null?' / '.(int)$c['usage_limit']:'' ?></td><td><?= $esc($c['status']) ?></td><td><a class="link-button" href="<?= $base ?>/restaurant/coupons/<?= (int)$c['id'] ?>/edit">Edit</a> <form method="post" action="<?= $base ?>/restaurant/coupons/<?= (int)$c['id'] ?>/delete" style="display:inline"><button class="link-button danger" onclick="return confirm('Delete this coupon?')">Delete</button></form></td></tr><?php endforeach; if(!$coupons): ?><tr><td colspan="8"><div class="empty-state">No coupons created yet.</div></td></tr><?php endif; ?></tbody></table></div></div>
